package com.hbm.extprop;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

import com.hbm.config.RadiationConfig;
import com.hbm.dim.trait.CBT_Atmosphere;
import com.hbm.config.ServerConfig;
import com.hbm.entity.mob.EntityDuck;
import com.hbm.handler.threading.PacketThreading;
import com.hbm.lib.ModDamageSource;
import com.hbm.main.MainRegistry;
import com.hbm.packet.PacketDispatcher;
import com.hbm.packet.toclient.AuxParticlePacketNT;
import com.hbm.packet.toclient.PlayerInformPacket;
import com.hbm.util.ChatBuilder;

import net.minecraftforge.fml.common.network.NetworkRegistry.TargetPoint;
import io.netty.buffer.ByteBuf;
import net.minecraft.block.Block;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.SharedMonsterAttributes;
import net.minecraft.entity.ai.attributes.AttributeModifier;
import net.minecraft.entity.ai.attributes.IAttributeInstance;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.init.Blocks;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.text.TextFormatting;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.World;
import net.minecraftforge.common.IExtendedEntityProperties;

public class HbmLivingProps implements IExtendedEntityProperties {

	public static final String key = "NTM_EXT_LIVING";
	public static final UUID digamma_UUID = UUID.fromString("2a3d8aec-5ab9-4218-9b8b-ca812bdf378b");
	public EntityLivingBase entity;

	/// VALS ///
	private float radiation;
	private float digamma;
	private int asbestos;
	public static final int maxAsbestos = 60 * 60 * 20;
	private int blacklung;
	public static final int maxBlacklung = 2 * 60 * 60 * 20;
	private float radEnv;
	private float radBuf;
	private int bombTimer;
	private int contagion;
	private int oil;
	private float activation;
	private int oxygen = 100;
	public int fire;
	public int phosphorus;
	public int balefire;
	public int blackFire;
	private List<ContaminationEffect> contamination = new ArrayList();
	private CBT_Atmosphere atmosphere;
	private boolean gravity = false;

	public HbmLivingProps(EntityLivingBase entity) {
		this.entity = entity;
	}

	/// DATA ///
	public static HbmLivingProps registerData(EntityLivingBase entity) {

		entity.registerExtendedProperties(key, new HbmLivingProps(entity));
		return (HbmLivingProps) entity.getExtendedProperties(key);
	}

	public static HbmLivingProps getData(EntityLivingBase entity) {

		HbmLivingProps props = (HbmLivingProps) entity.getExtendedProperties(key);
		return props != null ? props : registerData(entity);
	}

	/// RADIATION ///
	public static float getRadiation(EntityLivingBase entity) {
		if(!RadiationConfig.enableContamination)
			return 0;

		return getData(entity).radiation;
	}

	public static void setRadiation(EntityLivingBase entity, float rad) {
		if(RadiationConfig.enableContamination)
			getData(entity).radiation = rad;
	}

	public static void incrementRadiation(EntityLivingBase entity, float rad) {
		if(!RadiationConfig.enableContamination)
			return;

		HbmLivingProps data = getData(entity);
		float radiation = getData(entity).radiation + rad;

		if(radiation > 2500)
			radiation = 2500;
		if(radiation < 0)
			radiation = 0;

		data.setRadiation(entity, radiation);
	}

	/// NEUTRON ACTIVATION ///
	public static float getNeutronActivation(EntityLivingBase entity) {
		if(RadiationConfig.disableNeutron)
			return 0;

		return getData(entity).activation;
	}

	public static void setNeutronActivation(EntityLivingBase entity, float rad) {
		if(!RadiationConfig.disableNeutron)
			getData(entity).activation = rad;
	}

	public static void incrementNeutronActivation(EntityLivingBase entity, float rad) {
		if(RadiationConfig.disableNeutron)
			return;

		HbmLivingProps data = getData(entity);
		float neutrons = getData(entity).activation + rad;

		if(neutrons < 0)
			neutrons = 0;

		data.setNeutronActivation(entity, neutrons);
	}

	/// RAD ENV ///
	public static float getRadEnv(EntityLivingBase entity) {
		return getData(entity).radEnv;
	}

	public static void setRadEnv(EntityLivingBase entity, float rad) {
		getData(entity).radEnv = rad;
	}

	/// RAD BUF ///
	public static float getRadBuf(EntityLivingBase entity) {
		return getData(entity).radBuf;
	}

	public static void setRadBuf(EntityLivingBase entity, float rad) {
		getData(entity).radBuf = rad;
	}

	/// CONTAMINATION ///
	public static List<ContaminationEffect> getCont(EntityLivingBase entity) {
		return getData(entity).contamination;
	}

	public static void addCont(EntityLivingBase entity, ContaminationEffect cont) {
		getData(entity).contamination.add(cont);
	}

	/// DIGAMA ///
	public static float getDigamma(EntityLivingBase entity) {
		return getData(entity).digamma;
	}

	public static void setDigamma(EntityLivingBase entity, float digamma) {

		if(entity.worldObj.isRemote)
			return;

		if(entity instanceof EntityDuck)
			digamma = 0.0F;

		getData(entity).digamma = digamma;

		float healthMod = (float)Math.pow(0.5, digamma) - 1F;

		IAttributeInstance attributeinstance = entity.getAttributeMap().getAttributeInstance(SharedMonsterAttributes.maxHealth);

		try {
			attributeinstance.removeModifier(attributeinstance.getModifier(digamma_UUID));
		} catch(Exception ex) { }

		attributeinstance.applyModifier(new AttributeModifier(digamma_UUID, "digamma", healthMod, 2));

		if(entity.getHealth() > entity.getMaxHealth() && entity.getMaxHealth() > 0) {
			entity.setHealth(entity.getMaxHealth());
		}

		if((entity.getMaxHealth() <= 0 || digamma >= 10.0F) && entity.isEntityAlive()) {
			entity.setAbsorptionAmount(0);
			entity.attackEntityFrom(ModDamageSource.digamma, 500F);
			entity.setHealth(0);
			entity.onDeath(ModDamageSource.digamma);

			NBTTagCompound data = new NBTTagCompound();
			data.setString("type", "sweat");
			data.setInteger("count", 50);
			data.setInteger("block", Block.getIdFromBlock(Blocks.soul_sand));
			data.setInteger("entity", entity.getEntityId());
			PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, 0, 0, 0),  new TargetPoint(entity.dimension, entity.posX, entity.posY, entity.posZ, 50));
		}

		if(entity instanceof EntityPlayer) {

			float di = getData(entity).digamma;

			if(di > 0F)
				((EntityPlayer) entity).triggerAchievement(MainRegistry.digammaSee);
			if(di >= 2F)
				((EntityPlayer) entity).triggerAchievement(MainRegistry.digammaFeel);
			if(di >= 10F)
				((EntityPlayer) entity).triggerAchievement(MainRegistry.digammaKnow);
		}
	}

	public static void incrementDigamma(EntityLivingBase entity, float digamma) {

		if(entity instanceof EntityDuck)
			digamma = 0.0F;

		HbmLivingProps data = getData(entity);
		float dRad = getDigamma(entity) + digamma;

		if(dRad > 10)
			dRad = 10;
		if(dRad < 0)
			dRad = 0;

		data.setDigamma(entity, dRad);
	}


	/// ASBESTOS ///
	public static int getAsbestos(EntityLivingBase entity) {
		if(RadiationConfig.disableAsbestos) return 0;
		return getData(entity).asbestos;
	}

	public static void setAsbestos(EntityLivingBase entity, int asbestos) {
		if(RadiationConfig.disableAsbestos) return;
		getData(entity).asbestos = asbestos;

		if(asbestos >= maxAsbestos) {
			getData(entity).asbestos = 0;
			entity.attackEntityFrom(ModDamageSource.asbestos, 1000);
		}
	}

	public static void incrementAsbestos(EntityLivingBase entity, int asbestos) {
		if(RadiationConfig.disableAsbestos) return;
		setAsbestos(entity, getAsbestos(entity) + asbestos);

		if(entity instanceof EntityPlayerMP) {
			PacketDispatcher.wrapper.sendTo(new PlayerInformPacket(ChatBuilder.start("").nextTranslation("info.asbestos").color(TextFormatting.RED).flush(), MainRegistry.proxy.ID_GAS_HAZARD, 3000), (EntityPlayerMP) entity);
		}
	}

	//ATMOSPHERE//
	public static int getOxy(EntityLivingBase entity) {
		return getData(entity).oxygen;
	}

	public static void setOxy(EntityLivingBase entity, int oxygen) {
		if(oxygen <= 0) {
			if(entity.ticksExisted < 20) oxygen = 0; // limit overdamage effects when relogging

			int damageInterval = MathHelper.clamp_int(oxygen / 60 + 8, 1, 8);
			int damageAmount = MathHelper.clamp_int(-oxygen / 40 - 10, 1, Integer.MAX_VALUE);

			// Only damage every 4 ticks, giving the player more time to react
			if(entity.ticksExisted % damageInterval == 0) {
				entity.attackEntityFrom(ModDamageSource.oxyprime, damageAmount);
			}
		}

		getData(entity).oxygen = oxygen;
	}

	/// BLACK LUNG DISEASE ///
	public static int getBlackLung(EntityLivingBase entity) {
		if(RadiationConfig.disableCoal) return 0;
		return getData(entity).blacklung;
	}

	public static void setBlackLung(EntityLivingBase entity, int blacklung) {
		if(RadiationConfig.disableCoal) return;
		getData(entity).blacklung = blacklung;

		if(blacklung >= maxBlacklung) {
			getData(entity).blacklung = 0;
			entity.attackEntityFrom(ModDamageSource.blacklung, 1000);
		}
	}

	public static void incrementBlackLung(EntityLivingBase entity, int blacklung) {
		if(RadiationConfig.disableCoal) return;
		setBlackLung(entity, getBlackLung(entity) + blacklung);

		if(entity instanceof EntityPlayerMP) {
			PacketDispatcher.wrapper.sendTo(new PlayerInformPacket(ChatBuilder.start("").nextTranslation("info.coaldust").color(TextFormatting.RED).flush(), MainRegistry.proxy.ID_GAS_HAZARD, 3000), (EntityPlayerMP) entity);
		}
	}

	/// TIME BOMB ///
	public static int getTimer(EntityLivingBase entity) {
		return getData(entity).bombTimer;
	}

	public static void setTimer(EntityLivingBase entity, int bombTimer) {
		getData(entity).bombTimer = bombTimer;
	}

	/// CONTAGION ///
	public static int getContagion(EntityLivingBase entity) {
		if(!ServerConfig.ENABLE_MKU.get()) return 0;
		return getData(entity).contagion;
	}

	public static void setContagion(EntityLivingBase entity, int contageon) {
		getData(entity).contagion = contageon;
	}

	/// OIL ///
	public static int getOil(EntityLivingBase entity) { return getData(entity).oil; }
	public static void setOil(EntityLivingBase entity, int oil) { getData(entity).oil = oil; }

	/// ATMOSPHERE ///
	public static CBT_Atmosphere getAtmosphere(EntityLivingBase entity) {
		return getData(entity).atmosphere;
	}

	public static void setAtmosphere(EntityLivingBase entity, CBT_Atmosphere atmosphere) {
		HbmLivingProps data = getData(entity);
		data.atmosphere = atmosphere;
		data.gravity = atmosphere != null;
	}

	// and gravity (attached to atmospheres, for now)
	public static boolean hasGravity(EntityLivingBase entity) {
		return getData(entity).gravity;
	}

	@Override
	public void init(Entity entity, World world) { }

	public void serialize(ByteBuf buf) {
		buf.writeFloat(radiation);
		buf.writeFloat(digamma);
		buf.writeInt(asbestos);
		buf.writeInt(bombTimer);
		buf.writeInt(contagion);
		buf.writeInt(blacklung);
		buf.writeInt(oil);
		buf.writeInt(oxygen);
		buf.writeBoolean(gravity);
		buf.writeFloat(activation);
		buf.writeInt(fire);
		buf.writeInt(phosphorus);
		buf.writeInt(balefire);
		buf.writeInt(this.contamination.size());
		for (ContaminationEffect contaminationEffect : this.contamination) {
			contaminationEffect.serialize(buf); // long ass buffers? uh, yes please!
		}
	}

	public void deserialize(ByteBuf buf) {
		if(buf.readableBytes() > 0) {
			radiation = buf.readFloat();
			digamma = buf.readFloat();
			asbestos = buf.readInt();
			bombTimer = buf.readInt();
			contagion = buf.readInt();
			blacklung = buf.readInt();
			oil = buf.readInt();
			oxygen = buf.readInt();
			gravity = buf.readBoolean();
			activation = buf.readFloat();
			fire = buf.readInt();
			phosphorus = buf.readInt();
			balefire = buf.readInt();
			int size = buf.readInt();
			for (int i = 0; i < size; i++) {
				this.contamination.add(ContaminationEffect.deserialize(buf));
			}
		}
	}

	@Deprecated
	@Override
	public void saveNBTData(NBTTagCompound nbt) {

		NBTTagCompound props = new NBTTagCompound();

		props.setFloat("hfr_radiation", radiation);
		props.setFloat("hfr_digamma", digamma);
		props.setInteger("hfr_asbestos", asbestos);
		props.setInteger("hfr_bomb", bombTimer);
		if(ServerConfig.ENABLE_MKU.get()) props.setInteger("hfr_contagion", contagion);
		props.setInteger("hfr_blacklung", blacklung);
		props.setInteger("hfr_oil", oil);
		props.setInteger("hfr_oxygen", oxygen);
		props.setFloat("hfr_activation", activation);
		props.setBoolean("hfr_gravity", gravity);
		props.setInteger("hfr_fire", fire);
		props.setInteger("hfr_phosphorus", phosphorus);
		props.setInteger("hfr_balefire", balefire);
		props.setInteger("hfr_blackfire", blackFire);

		props.setInteger("hfr_cont_count", this.contamination.size());

		for(int i = 0; i < this.contamination.size(); i++) {
			this.contamination.get(i).save(props, i);
		}

		nbt.setTag("HbmLivingProps", props);
	}

	@Deprecated
	@Override
	public void loadNBTData(NBTTagCompound nbt) {

		NBTTagCompound props = (NBTTagCompound) nbt.getTag("HbmLivingProps");

		if(props != null) {
			radiation = props.getFloat("hfr_radiation");
			digamma = props.getFloat("hfr_digamma");
			asbestos = props.getInteger("hfr_asbestos");
			bombTimer = props.getInteger("hfr_bomb");
			if(ServerConfig.ENABLE_MKU.get()) contagion = props.getInteger("hfr_contagion");
			blacklung = props.getInteger("hfr_blacklung");
			oil = props.getInteger("hfr_oil");
			activation = props.getFloat("hfr_activation");
			oxygen = props.getInteger("hfr_oxygen");
			gravity = props.getBoolean("hfr_gravity");
			fire = props.getInteger("hfr_fire");
			phosphorus = props.getInteger("hfr_phosphorus");
			balefire = props.getInteger("hfr_balefire");
			blackFire = props.getInteger("hfr_blackfire");

			int cont = props.getInteger("hfr_cont_count");

			for(int i = 0; i < cont; i++) {
				this.contamination.add(ContaminationEffect.load(props, i));
			}
		}
	}

	public static class ContaminationEffect {

		public float maxRad;
		public int maxTime;
		public int time;
		public boolean ignoreArmor;

		public ContaminationEffect(float rad, int time, boolean ignoreArmor) {
			this.maxRad = rad;
			this.maxTime = this.time = time;
			this.ignoreArmor = ignoreArmor;
		}

		public float getRad() {
			return maxRad * ((float)time / (float)maxTime);
		}

		public void serialize(ByteBuf buf) {
			buf.writeFloat(this.maxRad);
			buf.writeInt(this.maxTime);
			buf.writeInt(this.time);
			buf.writeBoolean(ignoreArmor);
		}

		public static ContaminationEffect deserialize(ByteBuf buf) {
			float maxRad = buf.readFloat();
			int maxTime = buf.readInt();
			int time = buf.readInt();
			boolean ignoreArmor = buf.readBoolean();
			ContaminationEffect effect = new ContaminationEffect(maxRad, maxTime, ignoreArmor);
			effect.time = time;
			return effect;
		}

		public void save(NBTTagCompound nbt, int index) {
			NBTTagCompound me = new NBTTagCompound();
			me.setFloat("maxRad", this.maxRad);
			me.setInteger("maxTime", this.maxTime);
			me.setInteger("time", this.time);
			me.setBoolean("ignoreArmor", ignoreArmor);
			nbt.setTag("cont_" + index, me);
		}

		public static ContaminationEffect load(NBTTagCompound nbt, int index) {
			NBTTagCompound me = (NBTTagCompound) nbt.getTag("cont_" + index);
			float maxRad = me.getFloat("maxRad");
			int maxTime = nbt.getInteger("maxTime");
			int time = nbt.getInteger("time");
			boolean ignoreArmor = nbt.getBoolean("ignoreArmor");

			ContaminationEffect effect = new ContaminationEffect(maxRad, maxTime, ignoreArmor);
			effect.time = time;
			return effect;
		}
	}
}

HbmPlayerProps:
package com.hbm.extprop;

import com.hbm.entity.train.EntityRailCarBase;
import com.hbm.handler.ArmorModHandler;
import com.hbm.handler.HbmKeybinds.EnumKeybind;
import com.hbm.items.armor.ItemModShield;
import com.hbm.main.MainRegistry;
import com.hbm.tileentity.IGUIProvider;

import net.minecraftforge.fml.common.network.internal.FMLNetworkHandler;
import io.netty.buffer.ByteBuf;
import net.minecraft.entity.Entity;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.text.TextFormatting;
import net.minecraft.world.World;
import net.minecraftforge.common.IExtendedEntityProperties;

public class HbmPlayerProps implements IExtendedEntityProperties {

	public static final String key = "NTM_EXT_PLAYER";
	public EntityPlayer player;

	public boolean hasReceivedBook = false;

	public boolean enableHUD = true;
	public boolean enableBackpack = true;
	public boolean enableMagnet = true;

	private boolean[] keysPressed = new boolean[EnumKeybind.values().length];

	public boolean dashActivated = true;

	public static final int dashCooldownLength = 5;
	public int dashCooldown = 0;

	public int totalDashCount = 0;
	public int stamina = 0;

	public static final int plinkCooldownLength = 10;
	public int plinkCooldown = 0;

	public float shield = 0;
	public float maxShield = 0;
	public int lastDamage = 0;
	public int nitanCount = 0;
	public int nitanHealth = nitanCount*10;
	public static final float shieldCap = 100;

	public int reputation;

	public boolean isOnLadder = false;

	public boolean hasWarped = false;

	public int lastDimension = 0;

	public HbmPlayerProps(EntityPlayer player) {
		this.player = player;
	}

	public static HbmPlayerProps registerData(EntityPlayer player) {
		player.registerExtendedProperties(key, new HbmPlayerProps(player));
		return (HbmPlayerProps) player.getExtendedProperties(key);
	}

	public static HbmPlayerProps getData(EntityPlayer player) {
		HbmPlayerProps props = (HbmPlayerProps) player.getExtendedProperties(key);
		return props != null ? props : registerData(player);
	}

	public boolean getKeyPressed(EnumKeybind key) {
		return keysPressed[key.ordinal()];
	}

	public boolean isJetpackActive() {
		return this.enableBackpack && getKeyPressed(EnumKeybind.JETPACK);
	}

	public boolean isMagnetActive(){
		return this.enableMagnet;
	}

	public void setKeyPressed(EnumKeybind key, boolean pressed) {

		if(!getKeyPressed(key) && pressed) {

			if(key == EnumKeybind.TOGGLE_JETPACK) {

				if(!player.worldObj.isRemote) {
					this.enableBackpack = !this.enableBackpack;

					if(this.enableBackpack)
						MainRegistry.proxy.displayTooltip(TextFormatting.GREEN + "Jetpack ON", MainRegistry.proxy.ID_JETPACK);
					else
						MainRegistry.proxy.displayTooltip(TextFormatting.RED + "Jetpack OFF", MainRegistry.proxy.ID_JETPACK);
				}
			}
			if (key == EnumKeybind.TOGGLE_MAGNET){
				if (!player.worldObj.isRemote){
					this.enableMagnet = !this.enableMagnet;

					if(this.enableMagnet)
						MainRegistry.proxy.displayTooltip(TextFormatting.GREEN + "Magnet ON", MainRegistry.proxy.ID_MAGNET);
					else
						MainRegistry.proxy.displayTooltip(TextFormatting.RED + "Magnet OFF", MainRegistry.proxy.ID_MAGNET);
				}
			}
			if(key == EnumKeybind.TOGGLE_HEAD) {

				if(!player.worldObj.isRemote) {
					this.enableHUD = !this.enableHUD;

					if(this.enableHUD)
						MainRegistry.proxy.displayTooltip(TextFormatting.GREEN + "HUD ON", MainRegistry.proxy.ID_HUD);
					else
						MainRegistry.proxy.displayTooltip(TextFormatting.RED + "HUD OFF", MainRegistry.proxy.ID_HUD);
				}
			}

			if(key == EnumKeybind.TRAIN) {

				if(!this.player.worldObj.isRemote) {

					if(player.ridingEntity != null && player.ridingEntity instanceof EntityRailCarBase && player.ridingEntity instanceof IGUIProvider) {
						FMLNetworkHandler.openGui(player, MainRegistry.instance, 0, player.worldObj, player.ridingEntity.getEntityId(), 0, 0);
					}
				}
			}
		}

		keysPressed[key.ordinal()] = pressed;
	}

	public void setDashCooldown(int cooldown) {
		this.dashCooldown = cooldown;
		return;
	}

	public int getDashCooldown() {
		return this.dashCooldown;
	}

	public void setStamina(int stamina) {
		this.stamina = stamina;
		return;
	}

	public int getStamina() {
		return this.stamina;
	}

	public void setDashCount(int count) {
		this.totalDashCount = count;
		return;
	}

	public int getDashCount() {
		return this.totalDashCount;
	}

	public static void plink(EntityPlayer player, String sound, float volume, float pitch) {
		HbmPlayerProps props = HbmPlayerProps.getData(player);

		if(props.plinkCooldown <= 0) {
			player.worldObj.playSoundAtEntity(player, sound, volume, pitch);
			props.plinkCooldown = props.plinkCooldownLength;
		}
	}

	public float getEffectiveMaxShield() {

		float max = this.maxShield;

		if(player.getCurrentArmor(2) != null) {
			ItemStack[] mods = ArmorModHandler.pryMods(player.getCurrentArmor(2));
			if(mods[ArmorModHandler.kevlar] != null && mods[ArmorModHandler.kevlar].getItem() instanceof ItemModShield) {
				ItemModShield mod = (ItemModShield) mods[ArmorModHandler.kevlar].getItem();
				max += mod.shield;
			}
		}

		return max;
	}

	@Override
	public void init(Entity entity, World world) { }

	public void serialize(ByteBuf buf) {
		buf.writeBoolean(this.hasReceivedBook);
		buf.writeFloat(this.shield);
		buf.writeFloat(this.maxShield);
		buf.writeBoolean(this.enableBackpack);
		buf.writeBoolean(this.enableHUD);
		buf.writeInt(this.reputation);
		buf.writeBoolean(this.isOnLadder);
		buf.writeBoolean(this.enableMagnet);
	}

	public void deserialize(ByteBuf buf) {
		if(buf.readableBytes() > 0) {
			this.hasReceivedBook = buf.readBoolean();
			this.shield = buf.readFloat();
			this.maxShield = buf.readFloat();
			this.enableBackpack = buf.readBoolean();
			this.enableHUD = buf.readBoolean();
			this.reputation = buf.readInt();
			this.isOnLadder = buf.readBoolean();
			this.enableMagnet = buf.readBoolean();
		}
	}

	@Deprecated
	@Override
	public void saveNBTData(NBTTagCompound nbt) {

		NBTTagCompound props = new NBTTagCompound();

		props.setBoolean("hasReceivedBook", hasReceivedBook);
		props.setFloat("shield", shield);
		props.setFloat("maxShield", maxShield);
		props.setFloat("nitan", nitanCount);
		props.setBoolean("enableBackpack", enableBackpack);
		props.setBoolean("enableMagnet", enableMagnet);
		props.setBoolean("enableHUD", enableHUD);
		props.setInteger("reputation", reputation);
		props.setBoolean("isOnLadder", isOnLadder);
		props.setBoolean("hasWarped", hasWarped);
		props.setInteger("lastDimension", lastDimension);

		nbt.setTag("HbmPlayerProps", props);
	}

	@Deprecated
	@Override
	public void loadNBTData(NBTTagCompound nbt) {

		NBTTagCompound props = (NBTTagCompound) nbt.getTag("HbmPlayerProps");

		if(props != null) {
			this.hasReceivedBook = props.getBoolean("hasReceivedBook");
			this.shield = props.getFloat("shield");
			this.nitanCount = props.getInteger("nitan");
			this.maxShield = props.getFloat("maxShield");
			this.enableBackpack = props.getBoolean("enableBackpack");
			this.enableMagnet = props.getBoolean("enableMagnet");
			this.enableHUD = props.getBoolean("enableHUD");
			this.reputation = props.getInteger("reputation");
			this.isOnLadder = props.getBoolean("isOnLadder");
			this.hasWarped = props.getBoolean("hasWarped");
			this.lastDimension = props.getInteger("lastDimension");
		}
	}
}

onEntityDeath:
public void onEntityDeath(LivingDeathEvent event) {

		HbmLivingProps.setRadiation(event.entityLiving, 0);

		if(event.entity.worldObj.isRemote)
			return;

		if(GeneralConfig.enableCataclysm) {
			EntityBurningFOEQ foeq = new EntityBurningFOEQ(event.entity.worldObj);
			foeq.setPositionAndRotation(event.entity.posX, 500, event.entity.posZ, 0.0F, 0.0F);
			event.entity.worldObj.spawnEntityInWorld(foeq);
		}

		if(event.entity.getUniqueID().toString().equals(ShadyUtil.HbMinecraft) || event.entity.getCommandSenderName().equals("HbMinecraft")) {
			event.entity.dropItem(ModItems.book_of_, 1);
		}

		if(event.entity.getUniqueID().toString().equals(ShadyUtil.MellowRPG8)) {
			event.entity.entityDropItem(new ItemStack(ModBlocks.block_meteor, 1 + rand.nextInt(10)), 0.0F);
		}

		if(event.entity instanceof EntityCreeperTainted && event.source == ModDamageSource.boxcar) {

			for(Object o : event.entity.worldObj.getEntitiesWithinAABB(EntityPlayer.class, event.entity.boundingBox.expand(50, 50, 50))) {
				EntityPlayer player = (EntityPlayer)o;
				player.triggerAchievement(MainRegistry.bobHidden);
			}
		}
		CelestialBody body = CelestialBody.getBody(event.entity.worldObj);

		CBT_Invasion alien = body.getTrait(CBT_Invasion.class);
		if(alien != null) {
			if(event.entity instanceof EntitySiegeUFO) {

				alien.kills++;

				body.modifyTraits(alien);
			}else if (event.entity instanceof EntitySiegeCraft) {
				alien.kills += 3;

				body.modifyTraits(alien);
			}

			if(alien.wave >= 4 && event.entity instanceof EntityUFO) {
				HashMap<Class<? extends CelestialBodyTrait>, CelestialBodyTrait> currentTraits = body.getTraits(event.entity.worldObj);

				currentTraits.remove(CBT_Invasion.class);

			        for (Object obj : event.entity.worldObj.playerEntities) {
			            if (obj instanceof EntityPlayer) {
			                EntityPlayer player = (EntityPlayer) obj;
			                player.sendMessage(
			                    new TextComponentString("The Invasion Is Over!")
			                        .setStyle(new Style().setColor(TextFormatting.YELLOW))
			                );
			            }
			        }


				body.setTraits(event.entity.worldObj, currentTraits);


			}
		}


		if(!event.entityLiving.worldObj.isRemote) {

			if(event.source==ModDamageSource.eve)
			{
				for(int i = -1; i < 2; i++) {
					for(int j = -1; j < 2; j++) {
						for(int k = -1; k < 2; k++) {
							if(event.entityLiving.worldObj.getBlock((int)event.entityLiving.posX+i, (int)event.entityLiving.posY+j, (int)event.entityLiving.posZ+k)==Blocks.air)
							{
								if(ModBlocks.flesh_block.canPlaceBlockAt(event.entityLiving.worldObj, (int)event.entityLiving.posX+i, (int)event.entityLiving.posY+j, (int)event.entityLiving.posZ+k))
								{
									event.entityLiving.worldObj.setBlock((int)event.entityLiving.posX+i, (int)event.entityLiving.posY+j, (int)event.entityLiving.posZ+k, ModBlocks.flesh_block);
								}
							}
						}
					}
				}
			}

			if(event.source instanceof EntityDamageSource && ((EntityDamageSource)event.source).getEntity() instanceof EntityPlayer
					 && !(((EntityDamageSource)event.source).getEntity() instanceof FakePlayer)) {

				if(event.entityLiving instanceof EntitySpider && event.entityLiving.getRNG().nextInt(500) == 0) {
					event.entityLiving.dropItem(ModItems.spider_milk, 1);
				}

				if(event.entityLiving instanceof EntityCaveSpider && event.entityLiving.getRNG().nextInt(100) == 0) {
					event.entityLiving.dropItem(ModItems.serum, 1);
				}

				if(event.entityLiving instanceof EntityAnimal && event.entityLiving.getRNG().nextInt(500) == 0) {
					event.entityLiving.dropItem(ModItems.bandaid, 1);
				}

				if(event.entityLiving instanceof IMob) {
					if(event.entityLiving.getRNG().nextInt(1000) == 0) event.entityLiving.dropItem(ModItems.heart_piece, 1);
					if(event.entityLiving.getRNG().nextInt(250) == 0) event.entityLiving.dropItem(ModItems.key_red_cracked, 1);
					if(event.entityLiving.getRNG().nextInt(250) == 0) event.entityLiving.dropItem(ModItems.launch_code_piece, 1);
				}

				if(event.entityLiving instanceof EntityCyberCrab && event.entityLiving.getRNG().nextInt(500) == 0) {
					event.entityLiving.dropItem(ModItems.wd40, 1);
				}

				if(event.entityLiving instanceof EntityVillager&& event.entityLiving.getRNG().nextInt(1) == 0) {
					event.entityLiving.dropItem(ModItems.flesh, 5);
			}
		}
	}
}
